import statistics

import pytest
from hypothesis import given
from hypothesis import strategies as st

from median import median


@given(st.lists(st.integers(), min_size=1))
def test_property_matches_statistics(xs):
    """Property 1: median(xs) == statistics.median(xs) for any non-empty list."""
    assert median(xs) == statistics.median(xs)


@given(st.lists(st.integers(), min_size=1))
def test_property_between_min_and_max(xs):
    """Property 2: min(xs) <= median(xs) <= max(xs)."""
    assert min(xs) <= median(xs) <= max(xs)


@given(st.lists(st.integers(), min_size=1), st.data())
def test_property_permutation_invariant(xs, data):
    """Property 3: median is invariant under permutation of the input."""
    permuted = data.draw(st.permutations(xs))
    assert median(permuted) == median(xs)


def test_empty_list_raises():
    with pytest.raises(ValueError):
        median([])

